def capitalize(s):
    even_chars = []
    odd_chars = []
    for i, char in enumerate(s):
        if i % 2 == 0:
            even_chars.append(char.upper())
            odd_chars.append(char)
        else:
            even_chars.append(char)
            odd_chars.append(char.upper())
    return ["".join(even_chars), "".join(odd_chars)]
